test('invoiceTotals with standard tier (0%) discount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'STICKER', qty: 100 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 100 × €0.50 = €50.00
  // 0% tier discount = €0.00
  // 21% VAT on €50.00 = €10.50
  // Total = €50.00 - €0.00 + €10.50 = €60.50
  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1050);
  assert.equal(totals.total, 6050);
});

test('invoiceTotals calculates VAT per line after discount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 10 × €95.00 = €950.00 (subtotal)
  // 10% discount = €95.00
  // Amount after discount = €855.00
  // 21% VAT on €855.00 = €179.55
  // Total = €950.00 - €95.00 + €179.55 = €1,034.55
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.total, 103455);
});

test('invoiceTotals with zero VAT rate', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 1 × €600.00 = €600.00 (subtotal)
  // 0% discount
  // 0% VAT = €0.00
  // Total = €600.00 - €0.00 + €0.00 = €600.00
  assert.equal(totals.subtotal, 60000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 60000);
});

test('invoiceTotals with mixed VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // Line 1: 1 × €95.00 = €95.00, 21% VAT = €19.95
  // Line 2: 100 × €0.37 = €37.00, 9% VAT = €3.33
  // Line 3: 1 × €600.00 = €600.00, 0% VAT = €0.00
  // Subtotal: €732.00
  // VAT: €23.28
  // Total: €755.28
  assert.equal(totals.subtotal, 73200);
  assert.equal(totals.vat, 2328);
  assert.equal(totals.total, 75528);
});

test('invoiceTotals with 9% VAT rate', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'PRINT-A3', qty: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 10 × €2.49 = €24.90
  // 0% discount
  // 9% VAT on €24.90 = €2.241 -> €2.24
