test('invoiceTotals sums line totals', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, name: 'Development (hour)', vatRate: 21, discountPercent: 0 },
      { sku: 'STICKER', qty: 100, unitPrice: 50, name: 'Sticker sheet', vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 5 × €95.00 = €475.00, 21% VAT = €99.75
  // Line 2: 100 × €0.50 = €50.00, 21% VAT = €10.50
  // Subtotal: €525.00, VAT: €110.25, Total: €635.25
  assert.equal(totals.subtotal, 52500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 11025);
  assert.equal(totals.total, 63525);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, unitPrice: 120000, name: 'Logo package', vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // 1 × €1,200.00 = €1,200.00
  // 21% VAT = €252.00
  // Total = €1,452.00
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 25200);
  assert.equal(totals.total, 145200);
});

test('invoiceTotals with multiple high-value items', () => {
  const invoice = {
    customerId: 'C-005',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'BRAND-BOOK', qty: 2, unitPrice: 245000, name: 'Brand guidelines document', vatRate: 21, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', qty: 3, unitPrice: 60000, name: 'Brand workshop (day, VAT exempt)', vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = (2 * 245000) + (3 * 60000);
  // Line 1: 2 × €2,450.00 = €4,900.00, 21% VAT = €1,029.00
  // Line 2: 3 × €600.00 = €1,800.00, 0% VAT = €0.00
  // Subtotal: €6,700.00, VAT: €1,029.00, Total: €7,729.00
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 102900);
  assert.equal(totals.total, 772900);
  assert.equal(totals.subtotal, 670000);
});

test('invoiceTotals with VAT included in total', () => {
